print('Clean rows:', len(df_clean))
print(df_clean['State'].value_counts())

def parse_amount(val):
    if pd.isna(val):
        return 0.0
    s = str(val).strip()
    if s.lower() in ['-', 'na', 'amount', '']:
        return 0.0
    s_clean = s.replace('₹', '').replace(',', '').strip()
    m = re.match(r'^([0-9]*\.?[0-9]+)\s*([a-zA-Z]+)?$', s_clean)
    if not m:
