    unit = m.group(2)
    if unit:
        unit_l = unit.lower()
        if unit_l in ['l', 'lakh', 'lakhs']:
            return num * 100000
        elif unit_l in ['cr', 'crore', 'crores']:
            return num * 10000000
        elif unit_l in ['k', 'thousand']:
            return num * 1000
        else:
            return num
    else:
        return num

