def parse_amount(val):
    if pd.isna(val):
        return 0.0
    s = str(val).strip()
    if s.lower() in ['-', 'na', 'amount', '']:
        return 0.0
    s_clean = s.replace('₹', '').replace(',', '').strip()
    m = re.match(r'^([0-9]*\.?[0-9]+)\s*([a-zA-Z]+)?$', s_clean)
    if not m:
        m2 = re.search(r'([0-9]*\.?[0-9]+)', s_clean)
        if m2:
            try:
                return float(m2.group(1))
            except:
                return 0.0
        return 0.0
    num = float(m.group(1))
    unit = m.group(2)
    if unit:
        unit_l = unit.lower()
        if unit_l in ['l', 'lakh', 'lakhs']:
            return num * 100000
        elif unit_l in ['cr', 'crore', 'crores']:
            return num * 10000000
        elif unit_l in ['k', 'thousand']:
            return num * 1000
        else:
            return num
    else:
        return num

df_clean['Amount_num'] = df_clean['Amount'].apply(parse_amount)

# Verify parsing for each unique amount
unique_amounts = df_clean['Amount'].unique()
for amt in unique_amounts:
    print(amt, '->', parse_amount(amt))

# Compute totals per state
totals_state = df_clean.groupby('State')['Amount_num'].sum()
print(totals_state)
total_all = totals_state.sum()
pct_karnataka = totals_state.get('Karnataka',0)/total_all*100
